import cn from "clsx";
import type { ReactNode, SVGProps } from "react";

/**
 * Design system icon catalogue.
 *
 * Single `Icon` component with `name` and `size` props. Icons are sourced from
 * Radix Icons (https://icons.radix-ui.com); every Radix icon shares a 15×15
 * viewBox.
 *
 * Phosphor icons (https://phosphoricons.com, 256×256 viewBox) can be added
 * with separate stroke/fill helpers when needed.
 *
 * ## Usage
 *
 * ```tsx
 * <Icon name="caret-down" />
 * <Icon name="caret-up" size="lg" />
 * ```
 *
 * ## Naming convention
 *
 * Use kebab-case names that describe the glyph, aligned with Radix icon names
 * where possible (`caret-down`, `caret-up`, `cross-2`, etc.). The name at the call site is
 * for humans - each icon's render clause picks its helper directly.
 *
 * ## Sizing
 *
 * Sizing is driven by the `size` prop, which renders as a `data-size` attribute
 * on the SVG. CSS rules in `icon.css` map each value to width/height via
 * `--icon-size-*` tokens.
 *
 * ## Adding a Radix icon
 *
 * 1. Find the icon on https://icons.radix-ui.com.
 * 2. Click "Copy SVG".
 * 3. Add the name to `iconNames`.
 * 4. Add a `switch` case that calls `RadixSvg` and passes inner `<path>` (etc.)
 *    as children - no `<svg>` wrapper; the helper provides it.
 * 5. Drop `width` / `height` from the source SVG; sizing comes from CSS.
 * 6. Keep `fill="currentColor"` on paths (Radix ships paths filled, root `fill="none"`).
 *
 * ## Accessibility
 *
 * Icons render with `aria-hidden="true"` by default: they're decorative by
 * convention and typically sit next to a text label that conveys meaning. For
 * icon-only contexts the parent component is responsible for providing an
 * accessible name via `aria-label`, not the icon itself.
 *
 * Override via spread props if an icon genuinely conveys meaning on its own.
 */

const iconNames = [
    "caret-down",
    "caret-sort",
    "caret-up",
    "check",
    "link-break-2",
    "lock-closed",
    "magnifying-glass",
    "reset",
] as const;

export type IconName = (typeof iconNames)[number];
export type IconSize = "xsm" | "sm" | "md" | "lg";

export type IconProps = {
    name: IconName;
    size?: IconSize;
    className?: string;
} & Omit<SVGProps<SVGSVGElement>, "children">;

