type SvgShellProps = {
    name: string;
    size: IconSize;
    className?: string;
    children: ReactNode;
} & Omit<SVGProps<SVGSVGElement>, "children">;

/** Radix Icons: 15×15 viewBox, fill-based paths. */
function RadixSvg({ name, size, className, children, ...rest }: SvgShellProps) {
    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 15 15"
            fill="none"
            aria-hidden="true"
            className={cn("icon", className)}
            data-name={name}
            data-size={size}
            {...rest}
        >
            {children}
        </svg>
    );
}
